ops=json.loads("[{\"start\":17330,\"count\":1,\"lines\":[\"  const rememberReview=(id,reason)=>{job.issues=job.issues||[];if(!job.issues.some(x=>str(x.id)===str(id)))job.issues.push({id:str(id),reason,cloudStatus:'rejected'});job.ids=job.ids.filter(x=>str(x)!==str(id));save(job);};\",\"  const originalOf=row=>row.payload?.r340_original||row.payload;\",\"  const canonical=v=>v&&typeof v==='object'?(Array.isArray(v)?v.map(canonical):Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])]))):v;\",\"  const confirmed=(row,id)=>{const p=originalOf(row),c=job.confirmed?.[id];return !!p&&!!c&&str(p.batch_id)===str(job.batch)&&str(p.barcode)===str(c.barcode)&&int(p.counted_qty)===c.count&&(!c.original||JSON.stringify(canonical(c.original))===JSON.stringify(canonical(p)));};\",\"  const verifiedReview=(row,id)=>row?.status==='rejected'&&confirmed(row,id)&&row.result?.review_protocol==='r346'&&str(row.result.event_id)===str(id)&&str(row.result.batch_id)===str(job.batch)&&row.result.status==='review';\",\"  const exclude=async(id,reason,row)=>{\",\"   if(window.P7Cloud?.url!=='https://rmskuolsiqbzxuakofpb.supabase.co')throw Error('R346_wrong_store');\",\"   if(!job.ownerConfirmedCount||!confirmed(row,id))throw Error('R346_review_not_confirmed');\",\"   const durable=JSON.parse(localStorage.getItem(DB)||'null');\",\"   if(!Array.isArray(durable?.products)||!Array.isArray(state?.products)||durable.pos7InventoryApplied?.[id]||state.pos7InventoryApplied?.[id])throw Error('R346_review_local_state_unverified');\",\"   const p=originalOf(row);\",\"   const ack=await window.P7Cloud.rpc('pos7_inventory_mark_review_r346',{p_event_id:id,p_device:device,p_original:p,p_reason:str(reason).slice(0,500)});\",\"   if(ack?.status!=='review'||ack.review_protocol!=='r346'||str(ack.event_id)!==str(id)||str(ack.batch_id)!==str(job.batch))throw Error('R346_review_ack_unverified');\",\"   rememberReview(id,reason);\",\"  };\"]},{\"start\":17333,\"count\":1,\"lines\":[\"   if(!row){const found=await window.P7Cloud.req('/rest/v1/pos7_owner_commands?store_id=eq.pos7&event_id=eq.'+encodeURIComponent(id)+'&select=event_id,status,payload,result&limit=1');if(found?.length===1&&verifiedReview(found[0],id)){rememberReview(id,str(found[0].result.reason||'بحاجة إلى مراجعة'));continue;}throw Error('R346: حالة الطلب غير مؤكدة؛ لن نستبعد طلبًا معتمدًا أو مفقودًا');}\"]},{\"start\":17338,\"count\":1,\"lines\":[\"   if(job.reviewOnly?.includes(str(id))||!isSafe(row,cloud)){await exclude(id,'صنف يحتاج مراجعة الهوية أو المراجعة: '+str(row.payload?.barcode),row);continue;}\"]},{\"start\":17343,\"count\":1,\"lines\":[\"   if(matches.length!==1){await exclude(id,'باركود غير فريد؛ يحتاج مراجعة',row);continue;}\"]},{\"start\":17345,\"count\":2,\"lines\":[\"   if(str(matched.id)!==str(row.payload.r340_original?.product_id??row.payload.product_id)){await exclude(id,'تغير معرّف الصنف؛ حدّث كتالوج الهاتف وأعد المراجعة',row);continue;}\",\"   if(distinctProducts.has(str(matched.id))){await exclude(id,'الصنف مكرر في الدفعة؛ يحتاج مراجعة',row);continue;}\"]},{\"start\":17350,\"count\":1,\"lines\":[\"   if(prepared?.status==='review'){await exclude(id,str(prepared.reason||'هوية تحتاج مراجعة'),row);continue;}\"]},{\"start\":17354,\"count\":1,\"lines\":[\"   if(!repaired.ok){await exclude(id,'فشل تثبيت هوية '+str(row.payload.barcode)+': '+repaired.reason,row);continue;}\"]},{\"start\":17356,\"count\":1,\"lines\":[\"   if(!check?.ok){await exclude(id,'تعارض في بيانات التاب: '+str(check?.reason),row);continue;}\"]},{\"start\":17358,\"count\":2,\"lines\":[\"   if(anchor&&anchor.localId!==str(window.POS7_R340_guard.localId)){await exclude(id,'هوية الصنف المحلية تغيرت؛ أعد المراجعة',row);continue;}\",\"   if(anchor){const data=JSON.parse(localStorage.getItem(DB));const matches=data.products.filter(p=>str(p.id)===anchor.localId);if(matches.length!==1){await exclude(id,'مرجع الصنف غير متاح',row);continue;}try{pos7R343Target(data,matches[0],anchor,int(row.payload.counted_qty));}catch(err){await exclude(id,'حركة مخزون تحتاج مراجعة: '+str(err.message||err),row);continue;}}\"]},{\"start\":17491,\"count\":1,\"lines\":[\"   const btn=document.createElement('button');btn.textContent='✅ اعتماد '+safe.length+' وإبلاغ الهاتف بمراجعة '+(rs.length-safe.length)+' صنف';btn.disabled=!rs.length;\"]},{\"start\":17497,\"count\":1,\"lines\":[\"    const ids=rs.map(x=>str(x.event_id));\"]},{\"start\":17500,\"count\":1,\"lines\":[\"    if(!confirm('R342: أؤكد أن الكميات المجرودة تمثل العدد الفعلي المطلوب اعتماده الآن، مع إدخال أي بيع أو مرتجع حدث بعد العد في الحسبان. ستُسجل فروق مخزون التاب في سجل تسوية، ويُفحص مخزون السحابة قبل كل صنف. الأصناف غير المطابقة ستُرسل للهاتف بحالة بحاجة إلى مراجعة دون تغيير المخزون. هل تعتمد الدفعة؟'))return;\"]},{\"start\":17504,\"count\":1,\"lines\":[\"     save({version:343,batch,ids,anchors,reviewOnly:rs.filter(r=>!safe.includes(r)).map(r=>str(r.event_id)),confirmed:Object.fromEntries(rs.map(r=>[str(r.event_id),{barcode:str(r.payload.r340_original?.barcode??r.payload.barcode),count:int(r.payload.counted_qty),original:r.payload.r340_original||r.payload}])),approved:[],issues:[],state:'running',ownerConfirmedCount:true});resume();\"]}]")
